<span class="line"><span style="color:#ABB2BF;">betas </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> [</span><span style="color:#D19A66;">0.95</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0.9</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0.6</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">]</span></span>
